3	/**
4	 * Shared telephone normalization: strips every non-digit character, leaving the bare
5	 * digit sequence. Used both to canonicalize an incoming request's telephone and to
6	 * compare it against the telephones already stored on other owners.
7	 */
8	final class TelephoneNormalizer {
9	
10	    private TelephoneNormalizer() {
11	    }
12	
13	    static String digits(String raw) {
14	        return raw == null ? "" : raw.replaceAll("\\D", "");
15	    }
16	}
