1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the telephone on a create request: strips every non-digit character, then
9	 * requires exactly ten digits. Stores the 10-digit value back on the request (mutating
10	 * the shared {@code @Val} object) so {@link BuildOwner} and the response carry it; rejects
11	 * with {@link InvalidTelephoneException} (400) otherwise. Runs after {@link ValidateNewOwner}
12	 * has confirmed the field is present.
13	 */
14	public class NormalizeOwnerTelephone {
15	
16	    private static final int REQUIRED_DIGITS = 10;
17	
18	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
19	        String raw = request.getTelephone();
20	        String digits = TelephoneNormalizer.digits(raw);
21	        if (digits.length() != REQUIRED_DIGITS) {
22	            throw new InvalidTelephoneException(raw);
23	        }
24	        request.setTelephone(digits);
25	    }
26	}
