9	
10	    private final String telephone;
11	
12	    public DuplicateTelephoneException(String telephone) {
13	        super("Telephone is already used by another owner: " + telephone);
14	        this.telephone = telephone;
15	    }
16	
17	    public String getTelephone() {
18	        return this.telephone;
19	    }
20	}
